    case "undefined": return undefined;
    case "NaN": return NaN;
    case "Infinity": return Infinity;
    case "bigint": return BigInt(v.v);
    case "symbol": return Symbol("s");
    case "buffer": return Buffer.from(v.hex, "hex");
    case "url": return new URL(v.href);
    case "fn": return function fn() {};
