const add = (api, ...args) => cases.push({ api, args });
// What Linux answers.
for (const api of ["chownSync", "lchownSync", "chown", "lchown", "promises.chown", "promises.lchown"]) {
  add(api, F, "$me", "$me"); add(api, L, "$me", "$me"); add(api, F, -1, -1); add(api, F, 1234, 5678); add(api, L, 1234, 5678);
  add(api, F, 0, -1); add(api, F, -1, 0); add(api, A, "$me", "$me"); add(api, "", "$me", "$me"); add(api, "/work/file/under", "$me", "$me");
