  for (const name of ["chown", "lchown"]) out.shape[`promises.${name}`] = [fs.promises[name].name, fs.promises[name].length];
  const h = await fs.promises.open("/work/shape", "w"); out.shape["handle.chown"] = [h.chown.name, h.chown.length]; await h.close();
  for (const c of process.argv[2] === "answers" ? cases.slice(0, answered) : cases) out.cases.push({ ...c, result: await run(c) });
  process.stdout.write(JSON.stringify(out));
})();
